-- Passage rg8-theme-summary-p03
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('36f09db0-0b06-5387-95c7-e0f4e37728ea', 'rg8-theme-summary-p03', (select id from public.skills where slug = 'read-g8-theme-summary'), null,
        '6-8', $q$The Two Beavers$q$, $q$Two young beavers each set out to build a dam on the same wide creek. The first, a beaver named Flick, worked with a speed that drew a crowd. Herons stopped fishing to watch him, and a family of ducks paddled over to cheer. Flick piled branches high and packed them with mud in a single afternoon. "Look how tall it is," he called. "Mine will be finished by sunset!"

The second beaver, Marrow, worked farther downstream. She tested each branch by bending it before she used it, and she tossed away any that cracked. She pushed stones into the creek bed so the bottom of her dam would not slide. The ducks lost interest and paddled back to Flick. By sunset, Marrow's dam was barely half as tall as his.

"You will never finish," Flick laughed. "Nobody even watches you."

"I am not building it for them to watch," Marrow said, and she kept working.

Three nights later, heavy rain swelled the creek. The water rose against Flick's tall dam, found the cracked branches he had never checked, and pulled them loose one by one. By morning, his dam was scattered down the creek in pieces. Marrow's shorter dam was muddy and dripping, but it held.

Flick swam to her side, tired and quiet. Marrow handed him a branch. "Bend it first," she said. "Then we will build."$q$, 'draft')
