-- Passage rg8-theme-summary-p04
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('feb0921d-e7e7-5ed4-83c7-6817a1fb8590', 'rg8-theme-summary-p04', (select id from public.skills where slug = 'read-g8-theme-summary'), null,
        '6-8', $q$Number, Please$q$, $q$When Ms. Patel assigned the local history project, Zainab groaned. She had hoped to write about a famous inventor or a general. Instead, every student had to interview someone in town who was older than seventy.

Her neighbor, Mr. Eli Washington, agreed to talk on Saturday. Zainab set her phone on his kitchen table to record and read her first question from an index card. She expected a short answer and maybe a story about the weather.

Mr. Washington began with the telephone exchange. In 1958, when he was sixteen, he had worked nights connecting calls by hand. Each caller lifted a receiver, and a light blinked on his board. He plugged a cord into the right hole and asked, "Number, please?"

"Was it boring?" Zainab asked.

He laughed. "Not the night of the river flood." Water had covered the bridge, he explained, and families on the east side could not reach the doctor. For six hours he passed messages between neighbors, the fire station, and the clinic. He remembered which farm had a boat. He remembered whose grandmother needed medicine.

Zainab stopped looking at her index cards. She asked how the flood ended, what his supervisor said, and whether anyone thanked him. The recording ran for ninety minutes.

That night, she searched the county archive online. The flood had one paragraph in the newspaper, and it did not mention the telephone exchange at all. Zainab opened a new document and typed a title for her project: "The Night the Switchboard Held the Town Together."$q$, 'draft')
