  ('5010ac59-0f7e-5323-838d-46806f1120f2', null, (select id from public.skills where slug = 'read-g9-character-setting-plot'), null, 'hard',
   $q$How does Mateo's final choice not to count the extra hour show that he has changed?$q$, $q$[{"text":"It shows that he has already finished his twenty hours and no longer needs any.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"It shows that he now helps because he cares, not just to meet a requirement.","is_correct":true},{"text":"It shows that he is angry the library made him stay past the end of his shift.","is_correct":false,"misconception_token":"misreads-character"},{"text":"It shows that he forgot to sign the volunteer sheet because he was so busy.","is_correct":false,"misconception_token":"literal-reading"}]$q$::jsonb, $q$It shows that he now helps because he cares, not just to meet a requirement.$q$, $q$He began volunteering only for required hours, so choosing not to count extra time shows his motive has shifted to caring about the visitors. He stays by choice, so he is not angry.$q$, 'draft', '6ae20931-5b22-51dd-a9ce-24cadb34fd8a')
