-- Passage rg9-character-setting-plot-p08
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('12bc1dba-f924-5116-b826-af525ce9d544', 'rg9-character-setting-plot-p08', (select id from public.skills where slug = 'read-g9-character-setting-plot'), null,
        '9-12', $q$Mr. Ibarra at the Corner$q$, $q$For six years I walked past Mr. Ibarra
without really looking. He was part of the corner,
like the mailbox and the crack shaped like a lightning bolt.
He held up his red sign. The cars stopped.
I crossed with my earbuds in and did not say a word.

In March I heard he was retiring.
A notice went up in the office window:
Volunteers needed, mornings, Elm and Fourth.
I do not know why I signed my name.
Maybe because nobody else had.

He trained me for two weeks in the cold.
He knew the names of every child who crossed.
He knew which driver always rolled the stop
and which grandmother walked slowly on wet days.
He waved at buses like they were old friends.

I had thought the job was holding up a sign.
It turned out to be paying attention.
He said, "You stand here so they can stop worrying."
I wrote that down on the back of my hand.
By Friday the ink had faded. I still knew it.

Now I am the one in the yellow vest.
The little ones call me by my name.
Some of them cross with earbuds in, not looking.
I say good morning to them anyway.
One day, I think, they will say it back.$q$, 'draft')
