values
  ('863ae260-685d-5108-b306-7614aa5e6a4f', null, (select id from public.skills where slug = 'read-g9-comparing-texts'), null, 'easy',
   $q$Which idea from Text 1 does the poem in Text 2 carry over?$q$, $q$[{"text":"Leaders should solve difficult problems without asking ordinary people for help.","is_correct":false,"misconception_token":"reverses-meaning"},{"text":"Small contributions that seem weak alone can combine into something strong.","is_correct":true},{"text":"Talented individuals deserve more credit than the groups they belong to.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"Rushing water is a danger that every community must learn to avoid.","is_correct":false,"misconception_token":"too-narrow"}]$q$::jsonb, $q$Small contributions that seem weak alone can combine into something strong.$q$, $q$The stones "alone" could not hold back a puddle, and the speaker's part is "thin and plain," yet both join a strong whole. The stream appears only in Text 1, so the choice about water is too narrow.$q$, 'draft', 'a103a213-ac53-5802-b32a-a4cabb12163f')
