  ('4524a66a-3718-50df-8504-32e8014a45b9', null, (select id from public.skills where slug = 'read-g9-comparing-texts'), null, 'medium',
   $q$How does Text 2 change the point of view used in Text 1?$q$, $q$[{"text":"Text 1 is told by one of the elders, while Text 2 is told by an audience member watching the concert.","is_correct":false,"misconception_token":"misidentifies-narrator"},{"text":"Both texts are told by the same narrator, who moves from the village to the concert hall over time.","is_correct":false,"misconception_token":"confuses-texts"},{"text":"Text 1 speaks directly to the reader as \"you,\" while Text 2 describes the orchestra from far away.","is_correct":false,"misconception_token":"reverses-meaning"},{"text":"Text 1 tells the tale from outside the village, while Text 2 speaks as one contributor who is part of the group.","is_correct":true}]$q$::jsonb, $q$Text 1 tells the tale from outside the village, while Text 2 speaks as one contributor who is part of the group.$q$, $q$Text 1 uses a third-person storyteller, but the poem uses "I" and "my viola part," placing readers inside the group. The speaker plays in the orchestra, so the choice about an audience member misreads Text 2.$q$, 'draft', 'a103a213-ac53-5802-b32a-a4cabb12163f')
