  ('c909166a-33dd-50e6-a275-c9835009448f', null, (select id from public.skills where slug = 'read-g9-comparing-texts'), null, 'hard',
   $q$How does Text 2 transform the ending of the legend?$q$, $q$[{"text":"Peleku's question is left open, but Ana's grandmother helps her see the in-between space as a place of belonging.","is_correct":true},{"text":"Both characters decide to give up their roles so that they can return to a single community.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"Both endings show that carrying messages for others leads only to loneliness and regret.","is_correct":false,"misconception_token":"misreads-tone"},{"text":"Peleku finds a clear answer when the villages send gifts, but Ana's question stays completely unresolved.","is_correct":false,"misconception_token":"reverses-meaning"}]$q$::jsonb, $q$Peleku's question is left open, but Ana's grandmother helps her see the in-between space as a place of belonging.$q$, $q$Peleku ends "wondering," but Ana feels the space "less like a gap and more like a place she could stand" after being called "my bridge." The gifts do not answer Peleku's question, so the reversed choice misreads Text 1.$q$, 'draft', '2c170014-94cb-5ba5-958f-05a46a079359')
